-- InvenTour: o que a segunda revisão independente das 54 fichas achou.
-- Softsul Software, 20/11/2026. Ver docs/revisao-fichas-2011.md.
--
-- Núcleo: o texto do idioma Outros e o texto do Outras da acessibilidade
-- (rota externa e o subitem 6.1.21, que não tinha campo).
-- Catálogo: datas exatas em tabela (feriados da A1, inauguração dos
-- monumentos da B.6.2), premiação e reconhecimento múltiplos, veículos
-- próprios e de terceiros juntos, a linha MTur: outros nos cadastros das
-- B6 e a coluna para dizer qual é a esfera ou o instrumento Outros na proteção.

ALTER TABLE inventario_itens ADD COLUMN idiomas_outro VARCHAR(120) NULL COMMENT 'qual outro idioma' AFTER idiomas;
ALTER TABLE inventario_item_acessibilidade ADD COLUMN outro VARCHAR(255) NULL COMMENT 'o texto do Outras' AFTER opcoes;

